-- PostgreSQL 方言 schema, 由 schema.sql 转换生成 (见 /tmp/convert_schema.py)。
-- 与 SQLite 版保持同构: BOOLEAN -> INTEGER(0/1), TIMESTAMP -> TIMESTAMPTZ,
-- 自增主键 -> BIGINT GENERATED BY DEFAULT AS IDENTITY, ID 类列统一 BIGINT。


-- 1. 群组核心配置表
CREATE TABLE IF NOT EXISTS group_settings (
    group_id BIGINT PRIMARY KEY,
    group_title TEXT NOT NULL,
    is_active INTEGER DEFAULT 1,
    created_at TIMESTAMPTZ DEFAULT now(),
    updated_at TIMESTAMPTZ DEFAULT now()
);

-- 2. 独立消息模板库表 (解耦复用)
CREATE TABLE IF NOT EXISTS message_templates (
    template_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    group_id BIGINT,                        -- 允许为 NULL (系统全局模板) 或指定群专属
    template_name TEXT NOT NULL,             -- 模板名称 (例如: 新手日常欢迎语)
    media_type TEXT DEFAULT 'none',          -- 'none', 'photo', 'animation'
    media_source TEXT,                       -- 图片外链 URL 或 TG file_id
    content TEXT NOT NULL,                   -- 消息正文 (支持 HTML 与插值占位符)
    buttons_json TEXT DEFAULT '[]',          -- 按钮矩阵 JSON: [[{"text":"官网","url":"https://..."}]]
    created_at TIMESTAMPTZ DEFAULT now(),
    FOREIGN KEY(group_id) REFERENCES group_settings(group_id) ON DELETE CASCADE
);

-- 3. 入群验证配置表
CREATE TABLE IF NOT EXISTS group_captcha_settings (
    group_id BIGINT PRIMARY KEY,
    enabled INTEGER DEFAULT 1,
    captcha_type TEXT DEFAULT 'math',        -- 'click' (单选), 'math' (四则算术), 'choice' (图符匹配)
    timeout INTEGER DEFAULT 60,              -- 超时秒数 (默认 60s)
    action_on_fail TEXT DEFAULT 'kick',      -- 'kick' (踢出可再进) 或 'ban' (拉黑)
    auto_delete_prompt INTEGER DEFAULT 1, -- 完成/超时后是否自动删除验证题
    FOREIGN KEY(group_id) REFERENCES group_settings(group_id) ON DELETE CASCADE
);

-- 4. 待完成验证任务跟踪表 (内存与恢复使用)
CREATE TABLE IF NOT EXISTS pending_verifications (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    group_id BIGINT NOT NULL,
    user_id BIGINT NOT NULL,
    message_id BIGINT NOT NULL,
    expected_answer TEXT NOT NULL,
    expire_at TIMESTAMPTZ NOT NULL,
    created_at TIMESTAMPTZ DEFAULT now(),
    UNIQUE(group_id, user_id)
);

-- 5. 入群欢迎配置表 (关联消息模板)
CREATE TABLE IF NOT EXISTS group_welcome_settings (
    group_id BIGINT PRIMARY KEY,
    enabled INTEGER DEFAULT 1,
    active_template_id BIGINT,              -- 当前生效的消息模板 ID
    delete_ttl INTEGER DEFAULT 120,          -- 自动撤回秒数 (0=不撤回, 默认 120 秒)
    clean_previous INTEGER DEFAULT 1,     -- 进新人时是否自动撤回上一条未销毁欢迎语
    last_welcome_message_id BIGINT DEFAULT NULL,
    FOREIGN KEY(group_id) REFERENCES group_settings(group_id) ON DELETE CASCADE,
    FOREIGN KEY(active_template_id) REFERENCES message_templates(template_id) ON DELETE SET NULL
);

-- 6. 敏感词规则表
CREATE TABLE IF NOT EXISTS group_sensitive_rules (
    rule_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    group_id BIGINT NOT NULL,
    pattern TEXT NOT NULL,                   -- 敏感词或正则表达式
    match_type TEXT DEFAULT 'contains',      -- 'contains', 'exact', 'regex'
    punish_action TEXT DEFAULT 'delete_only',-- 'delete_only', 'mute', 'kick', 'ban'
    mute_duration INTEGER DEFAULT 3600,      -- 禁言时长(秒)
    created_at TIMESTAMPTZ DEFAULT now(),
    FOREIGN KEY(group_id) REFERENCES group_settings(group_id) ON DELETE CASCADE
);

-- 7. 广告与外链安全策略表
CREATE TABLE IF NOT EXISTS group_moderation_settings (
    group_id BIGINT PRIMARY KEY,
    block_tg_links INTEGER DEFAULT 1,     -- 拦截 t.me 链接
    block_all_urls INTEGER DEFAULT 0,    -- 拦截一切外部链接
    block_forwards INTEGER DEFAULT 0,    -- 拦截频道/他人转发消息
    send_warning_msg INTEGER DEFAULT 1,   -- 是否发送违规告警
    warning_ttl INTEGER DEFAULT 5,           -- 警告消息自动销毁秒数 (默认 5 秒)
    max_warn_count INTEGER DEFAULT 3,        -- 累计违规封禁阈值
    warn_action TEXT DEFAULT 'kick',         -- 达到阈值处罚: 'kick', 'ban', 'mute'
    moderate_admins INTEGER DEFAULT 0,       -- 连管理员也拦截 (测试用, 默认关: 管理员豁免)
    FOREIGN KEY(group_id) REFERENCES group_settings(group_id) ON DELETE CASCADE
);

-- 8. 用户违规累计表
CREATE TABLE IF NOT EXISTS user_warn_records (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    group_id BIGINT NOT NULL,
    user_id BIGINT NOT NULL,
    warn_count INTEGER DEFAULT 1,
    last_violation_time TIMESTAMPTZ DEFAULT now(),
    UNIQUE(group_id, user_id),
    FOREIGN KEY(group_id) REFERENCES group_settings(group_id) ON DELETE CASCADE
);

-- 9. 本地 Ollama AI 配置表
CREATE TABLE IF NOT EXISTS group_llm_settings (
    group_id BIGINT PRIMARY KEY,
    enabled INTEGER DEFAULT 0,
    base_url TEXT DEFAULT 'http://host.docker.internal:11434',
    model_name TEXT DEFAULT 'qwen2.5:7b',
    system_prompt TEXT DEFAULT '你是一个群组智能管家，性格幽默、有问必答、语气简短有力。',
    trigger_on_mention INTEGER DEFAULT 1,
    trigger_on_reply INTEGER DEFAULT 1,
    trigger_keywords TEXT DEFAULT '',        -- 逗号分隔的触发关键词 (如 "ai ,小助手 ")，句中包含即触发
    context_enabled INTEGER DEFAULT 1,
    context_mode TEXT DEFAULT 'user_isolated', -- 'shared' (群共享) 或 'user_isolated' (按人隔离)
    context_limit INTEGER DEFAULT 6,         -- 历史记忆保留轮数
    FOREIGN KEY(group_id) REFERENCES group_settings(group_id) ON DELETE CASCADE
);

-- 10. AI 对话记忆存储表
CREATE TABLE IF NOT EXISTS llm_chat_history (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    group_id BIGINT NOT NULL,
    user_id BIGINT NOT NULL,
    role TEXT NOT NULL,                      -- 'user' 或 'assistant'
    content TEXT NOT NULL,
    created_at TIMESTAMPTZ DEFAULT now()
);

-- 11. 紧急模式与权限控制表 (支撑面板第 6 大模块)
CREATE TABLE IF NOT EXISTS group_emergency_settings (
    group_id BIGINT PRIMARY KEY,
    lockdown_mode INTEGER DEFAULT 0,     -- 一键防爆群全员禁言锁群开关
    raid_protection INTEGER DEFAULT 0,   -- 防拉人爆群自动踢出新入群者
    enable_admin_call INTEGER DEFAULT 1,  -- 允许群成员使用 /admin 或 @admin 呼叫管理员
    notify_admins_dm INTEGER DEFAULT 0,  -- 触发 /admin 时是否私聊通知管理员
    FOREIGN KEY(group_id) REFERENCES group_settings(group_id) ON DELETE CASCADE
);

-- 12. 管理员与系统操作审计日志表 (支撑面板第 7 大模块)
CREATE TABLE IF NOT EXISTS admin_audit_logs (
    log_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    group_id BIGINT NOT NULL,
    operator_id BIGINT NOT NULL,
    operator_name TEXT NOT NULL,
    action_type TEXT NOT NULL,               -- 例如 'update_captcha', 'lockdown_on', 'ban_user'
    detail TEXT NOT NULL,
    created_at TIMESTAMPTZ DEFAULT now(),
    FOREIGN KEY(group_id) REFERENCES group_settings(group_id) ON DELETE CASCADE
);

-- 13. 广告白名单用户表 (豁免内容安全拦截)
CREATE TABLE IF NOT EXISTS group_whitelist (
    group_id BIGINT NOT NULL,
    user_id BIGINT NOT NULL,
    username TEXT DEFAULT '',
    note TEXT DEFAULT '',
    created_at TIMESTAMPTZ DEFAULT now(),
    UNIQUE(group_id, user_id),
    FOREIGN KEY(group_id) REFERENCES group_settings(group_id) ON DELETE CASCADE
);

-- 14. 群成员档案表 (成员管理与消息统计)
CREATE TABLE IF NOT EXISTS group_members (
    group_id BIGINT NOT NULL,
    user_id BIGINT NOT NULL,
    username TEXT DEFAULT '',
    first_name TEXT DEFAULT '',
    is_admin INTEGER DEFAULT 0,
    message_count INTEGER DEFAULT 0,
    last_seen TIMESTAMPTZ,
    joined_at TIMESTAMPTZ DEFAULT now(),
    UNIQUE(group_id, user_id),
    FOREIGN KEY(group_id) REFERENCES group_settings(group_id) ON DELETE CASCADE
);

-- 15. 群消息归档表 (消息管理与消息统计, 仅保留每群最新 500 条)
CREATE TABLE IF NOT EXISTS group_messages (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    group_id BIGINT NOT NULL,
    message_id BIGINT NOT NULL,
    user_id BIGINT NOT NULL,
    username TEXT DEFAULT '',
    text TEXT DEFAULT '',
    created_at TIMESTAMPTZ DEFAULT now(),
    FOREIGN KEY(group_id) REFERENCES group_settings(group_id) ON DELETE CASCADE
);
CREATE INDEX IF NOT EXISTS idx_group_messages_group_time ON group_messages(group_id, id DESC);

-- 16. 关键词自动回复表
CREATE TABLE IF NOT EXISTS keyword_replies (
    reply_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    group_id BIGINT NOT NULL,
    keyword TEXT NOT NULL,
    match_type TEXT DEFAULT 'contains',      -- 'contains', 'exact'
    reply_text TEXT NOT NULL,
    enabled INTEGER DEFAULT 1,
    created_at TIMESTAMPTZ DEFAULT now(),
    FOREIGN KEY(group_id) REFERENCES group_settings(group_id) ON DELETE CASCADE
);

-- 17. 定时发送任务表 (每天 HH:MM, 时区 Asia/Shanghai)
CREATE TABLE IF NOT EXISTS scheduled_messages (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    group_id BIGINT NOT NULL,
    content TEXT NOT NULL,
    send_time TEXT NOT NULL,                 -- 'HH:MM' 24 小时制
    enabled INTEGER DEFAULT 1,
    last_sent_date TEXT,                     -- 最近一次发送日期 'YYYY-MM-DD'
    created_at TIMESTAMPTZ DEFAULT now(),
    FOREIGN KEY(group_id) REFERENCES group_settings(group_id) ON DELETE CASCADE
);

-- 18. 强制订阅配置表
CREATE TABLE IF NOT EXISTS group_force_subscribe (
    group_id BIGINT PRIMARY KEY,
    enabled INTEGER DEFAULT 0,
    channel TEXT DEFAULT '',                 -- 频道用户名 (如 @xxx) 或频道 ID
    prompt_text TEXT DEFAULT '请先加入指定频道后再发言。',
    FOREIGN KEY(group_id) REFERENCES group_settings(group_id) ON DELETE CASCADE
);

-- ==================== Batch 2: 积分经济 + 抽奖游戏 + 其余模块 ====================

-- 19. 用户积分余额表
CREATE TABLE IF NOT EXISTS user_points (
    group_id BIGINT NOT NULL,
    user_id BIGINT NOT NULL,
    balance INTEGER DEFAULT 0,
    total_earned INTEGER DEFAULT 0,
    last_signin_date TEXT,                   -- 最近一次签到日期 'YYYY-MM-DD'
    signin_streak INTEGER DEFAULT 0,         -- 连续签到天数
    updated_at TIMESTAMPTZ DEFAULT now(),
    UNIQUE(group_id, user_id),
    FOREIGN KEY(group_id) REFERENCES group_settings(group_id) ON DELETE CASCADE
);

-- 20. 积分变更日志表 (仅保留 30 天, 由后台任务定期清理)
CREATE TABLE IF NOT EXISTS point_logs (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    group_id BIGINT NOT NULL,
    user_id BIGINT NOT NULL,
    delta INTEGER NOT NULL,                  -- 正数=获得, 负数=消费
    reason TEXT DEFAULT '',
    created_at TIMESTAMPTZ DEFAULT now(),
    FOREIGN KEY(group_id) REFERENCES group_settings(group_id) ON DELETE CASCADE
);
CREATE INDEX IF NOT EXISTS idx_point_logs_group_time ON point_logs(group_id, id DESC);

-- 21. 积分获取规则表
CREATE TABLE IF NOT EXISTS point_rules (
    rule_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    group_id BIGINT NOT NULL,
    trigger_action TEXT NOT NULL,            -- 'first_message' | 'every_message' | 'random_message'
    points INTEGER NOT NULL DEFAULT 1,
    chance INTEGER DEFAULT 100,              -- 仅 random_message 使用: 中奖概率 1-100
    enabled INTEGER DEFAULT 1,
    created_at TIMESTAMPTZ DEFAULT now(),
    FOREIGN KEY(group_id) REFERENCES group_settings(group_id) ON DELETE CASCADE
);

-- 22. 积分系统设置表
CREATE TABLE IF NOT EXISTS point_settings (
    group_id BIGINT PRIMARY KEY,
    alias TEXT DEFAULT '积分',
    daily_max INTEGER DEFAULT 0,             -- 每人每日发言积分上限, 0=不限
    decimals INTEGER DEFAULT 0,          -- 是否显示小数位 (仅展示)
    auto_clear_inactive INTEGER DEFAULT 0,
    signin_points INTEGER DEFAULT 10,        -- 签到奖励积分
    streak_bonus_points INTEGER DEFAULT 5,   -- 连续签到>=3 天额外奖励
    enabled INTEGER DEFAULT 1,
    FOREIGN KEY(group_id) REFERENCES group_settings(group_id) ON DELETE CASCADE
);

-- 23. 积分兑换商品表 (用户发送关键词兑换)
CREATE TABLE IF NOT EXISTS point_redemptions (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    group_id BIGINT NOT NULL,
    keyword TEXT NOT NULL,                   -- 兑换关键词 (群内发送即兑换)
    cost INTEGER NOT NULL DEFAULT 0,         -- 所需积分
    description TEXT DEFAULT '',
    enabled INTEGER DEFAULT 1,
    created_at TIMESTAMPTZ DEFAULT now(),
    FOREIGN KEY(group_id) REFERENCES group_settings(group_id) ON DELETE CASCADE
);

-- 24. 积分兑换记录表
CREATE TABLE IF NOT EXISTS point_redemption_records (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    group_id BIGINT NOT NULL,
    user_id BIGINT NOT NULL,
    redemption_id BIGINT NOT NULL,
    keyword TEXT DEFAULT '',
    cost INTEGER DEFAULT 0,
    created_at TIMESTAMPTZ DEFAULT now(),
    FOREIGN KEY(group_id) REFERENCES group_settings(group_id) ON DELETE CASCADE
);

-- 25. 抽奖活动表
CREATE TABLE IF NOT EXISTS lotteries (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    group_id BIGINT NOT NULL,
    lottery_type TEXT NOT NULL,              -- 'msg_count' | 'msg_rank' | 'signin_count' | 'invite_count' | 'points_scratch' | 'points_timed'
    title TEXT NOT NULL,
    keyword TEXT DEFAULT '抽奖',             -- 参与关键字
    draw_keyword TEXT DEFAULT '开奖',         -- 开奖关键字
    start_at TEXT,                           -- 活动开始时间 (ISO, 可空)
    end_at TEXT,                             -- 活动结束时间 (ISO, 可空, 定时开奖用)
    threshold INTEGER DEFAULT 0,             -- 参与门槛: 发言数 / 排名名次 / 签到天数 / 邀请人数
    draw_mode TEXT DEFAULT 'full',           -- 'full' 满人开奖 | 'timed' 定时开奖
    cost_per_draw INTEGER DEFAULT 0,         -- 刮刮乐每次消耗积分
    max_draws_per_user INTEGER DEFAULT 1,    -- 每人可抽次数 (刮刮乐)
    status TEXT DEFAULT 'active',            -- 'active' | 'ended'
    created_at TIMESTAMPTZ DEFAULT now(),
    FOREIGN KEY(group_id) REFERENCES group_settings(group_id) ON DELETE CASCADE
);

-- 26. 抽奖奖品表
CREATE TABLE IF NOT EXISTS lottery_prizes (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    lottery_id BIGINT NOT NULL,
    prize_name TEXT NOT NULL,
    total INTEGER NOT NULL DEFAULT 1,        -- 奖品总份数
    drawn INTEGER NOT NULL DEFAULT 0,        -- 已抽出份数
    FOREIGN KEY(lottery_id) REFERENCES lotteries(id) ON DELETE CASCADE
);

-- 27. 抽奖参与记录表
CREATE TABLE IF NOT EXISTS lottery_entries (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    lottery_id BIGINT NOT NULL,
    user_id BIGINT NOT NULL,
    username TEXT DEFAULT '',
    created_at TIMESTAMPTZ DEFAULT now(),
    UNIQUE(lottery_id, user_id),
    FOREIGN KEY(lottery_id) REFERENCES lotteries(id) ON DELETE CASCADE
);

-- 28. 抽奖中奖记录表
CREATE TABLE IF NOT EXISTS lottery_draws (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    lottery_id BIGINT NOT NULL,
    user_id BIGINT NOT NULL,
    username TEXT DEFAULT '',
    prize_name TEXT NOT NULL,
    created_at TIMESTAMPTZ DEFAULT now(),
    FOREIGN KEY(lottery_id) REFERENCES lotteries(id) ON DELETE CASCADE
);

-- 28b. 刮刮乐游玩次数记录表 (每次刮算一次, 不受 lottery_entries 唯一约束限制)
CREATE TABLE IF NOT EXISTS lottery_plays (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    lottery_id BIGINT NOT NULL,
    user_id BIGINT NOT NULL,
    created_at TIMESTAMPTZ DEFAULT now(),
    FOREIGN KEY(lottery_id) REFERENCES lotteries(id) ON DELETE CASCADE
);

-- 29. 积分竞猜活动表
CREATE TABLE IF NOT EXISTS guesses (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    group_id BIGINT NOT NULL,
    title TEXT NOT NULL,
    question TEXT NOT NULL,
    cost_per_bet INTEGER NOT NULL DEFAULT 10,  -- 每次下注消耗积分
    odds_mode TEXT DEFAULT 'prize',           -- 'prize' 奖品模式 | 'odds' 赔率模式
    prize_pool INTEGER DEFAULT 0,             -- 奖品模式: 获胜者平分奖池
    prize_amount INTEGER DEFAULT 0,           -- 奖品模式: 每位获胜者固定奖金 (优先于奖池平分, 0=用奖池平分)
    status TEXT DEFAULT 'active',             -- 'active' | 'closed'
    winning_option_id BIGINT,                -- 中奖选项 ID
    posted_message_id BIGINT,                -- 已发布的竞猜消息 ID
    created_at TIMESTAMPTZ DEFAULT now(),
    FOREIGN KEY(group_id) REFERENCES group_settings(group_id) ON DELETE CASCADE
);

-- 30. 竞猜选项表
CREATE TABLE IF NOT EXISTS guess_options (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    guess_id BIGINT NOT NULL,
    option_text TEXT NOT NULL,
    odds REAL DEFAULT 2.0,                   -- 赔率模式: 该选项赔率
    FOREIGN KEY(guess_id) REFERENCES guesses(id) ON DELETE CASCADE
);

-- 31. 竞猜下注记录表
CREATE TABLE IF NOT EXISTS guess_bets (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    guess_id BIGINT NOT NULL,
    user_id BIGINT NOT NULL,
    username TEXT DEFAULT '',
    option_id BIGINT NOT NULL,
    amount INTEGER NOT NULL DEFAULT 0,       -- 下注积分
    paid_out INTEGER DEFAULT 0,              -- 已派发奖金 (0=未派发)
    created_at TIMESTAMPTZ DEFAULT now(),
    FOREIGN KEY(guess_id) REFERENCES guesses(id) ON DELETE CASCADE
);

-- 32. 积分骰子游戏设置表
CREATE TABLE IF NOT EXISTS dice_settings (
    group_id BIGINT PRIMARY KEY,
    enabled INTEGER DEFAULT 0,
    cost_per_round INTEGER DEFAULT 10,       -- 每局消耗积分
    payout_multiplier REAL DEFAULT 2.0,      -- 获胜赔付倍数
    house_cut_percent INTEGER DEFAULT 0,     -- 系统抽成百分比 (仅记录展示)
    FOREIGN KEY(group_id) REFERENCES group_settings(group_id) ON DELETE CASCADE
);

-- 33. 积分骰子游戏记录表
CREATE TABLE IF NOT EXISTS dice_records (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    group_id BIGINT NOT NULL,
    user_id BIGINT NOT NULL,
    username TEXT DEFAULT '',
    cost INTEGER NOT NULL DEFAULT 0,
    user_roll INTEGER DEFAULT 0,
    bot_roll INTEGER DEFAULT 0,
    result TEXT DEFAULT 'lose',              -- 'win' | 'lose' | 'draw'
    payout INTEGER DEFAULT 0,
    created_at TIMESTAMPTZ DEFAULT now(),
    FOREIGN KEY(group_id) REFERENCES group_settings(group_id) ON DELETE CASCADE
);

-- 34. 轮播广告表
CREATE TABLE IF NOT EXISTS rotating_ads (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    group_id BIGINT NOT NULL,
    image_url TEXT DEFAULT '',
    link_url TEXT DEFAULT '',
    text TEXT DEFAULT '',                    -- 广告文案 (无图时使用)
    enabled INTEGER DEFAULT 1,
    created_at TIMESTAMPTZ DEFAULT now(),
    FOREIGN KEY(group_id) REFERENCES group_settings(group_id) ON DELETE CASCADE
);

-- 35. 轮播广告设置表
CREATE TABLE IF NOT EXISTS rotating_ads_settings (
    group_id BIGINT PRIMARY KEY,
    enabled INTEGER DEFAULT 0,
    interval_minutes INTEGER DEFAULT 60,     -- 轮播间隔 (分钟)
    display_seconds INTEGER DEFAULT 0,       -- 广告展示时长 (秒, 0=不自动删除)
    last_ad_index INTEGER DEFAULT -1,        -- 上次发送的广告下标 (轮询用)
    last_post_at TEXT,                       -- 上次发送时间 (ISO)
    FOREIGN KEY(group_id) REFERENCES group_settings(group_id) ON DELETE CASCADE
);

-- 36. 邀请记录表
CREATE TABLE IF NOT EXISTS invites (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    group_id BIGINT NOT NULL,
    inviter_id BIGINT,                      -- 邀请人 (邀请链接创建者, 未知时为 NULL)
    invited_id BIGINT NOT NULL,             -- 被邀请入群者
    created_at TIMESTAMPTZ DEFAULT now(),
    UNIQUE(group_id, invited_id),
    FOREIGN KEY(group_id) REFERENCES group_settings(group_id) ON DELETE CASCADE
);

-- 37. 定时关群任务表 (每天 HH:MM-HH:MM 窗口内全员禁言)
CREATE TABLE IF NOT EXISTS scheduled_lockdowns (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    group_id BIGINT NOT NULL,
    start_time TEXT NOT NULL,                -- 'HH:MM'
    end_time TEXT NOT NULL,                  -- 'HH:MM'
    enabled INTEGER DEFAULT 1,
    created_at TIMESTAMPTZ DEFAULT now(),
    FOREIGN KEY(group_id) REFERENCES group_settings(group_id) ON DELETE CASCADE
);

-- 38. 话术关群关键词表
CREATE TABLE IF NOT EXISTS lockdown_keywords (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    group_id BIGINT NOT NULL,
    keyword TEXT NOT NULL,
    lock_minutes INTEGER DEFAULT 30,         -- 触发后锁群时长 (分钟)
    enabled INTEGER DEFAULT 1,
    allow_admin_trigger INTEGER DEFAULT 0,   -- 管理员也可触发 (测试用, 默认关: 管理员豁免)
    created_at TIMESTAMPTZ DEFAULT now(),
    FOREIGN KEY(group_id) REFERENCES group_settings(group_id) ON DELETE CASCADE
);

-- 39. 群锁群状态表 (定时关群/话术关群的锁状态, 与紧急模式互不干扰)
CREATE TABLE IF NOT EXISTS group_lock_state (
    group_id BIGINT PRIMARY KEY,
    locked INTEGER DEFAULT 0,
    source TEXT DEFAULT '',                  -- 'schedule' | 'keyword'
    locked_until TEXT,                       -- 关键词锁的到期时间 (ISO)
    schedule_id BIGINT,                     -- 定时关群任务 ID
    FOREIGN KEY(group_id) REFERENCES group_settings(group_id) ON DELETE CASCADE
);

-- 40. 退群拉黑开关表
CREATE TABLE IF NOT EXISTS group_leave_ban (
    group_id BIGINT PRIMARY KEY,
    enabled INTEGER DEFAULT 0,
    FOREIGN KEY(group_id) REFERENCES group_settings(group_id) ON DELETE CASCADE
);

-- 41. 用户改名监控开关表
CREATE TABLE IF NOT EXISTS group_rename_watch (
    group_id BIGINT PRIMARY KEY,
    enabled INTEGER DEFAULT 0,
    FOREIGN KEY(group_id) REFERENCES group_settings(group_id) ON DELETE CASCADE
);

-- 42. 群底部按钮表 (群内发送"广告"弹出)
CREATE TABLE IF NOT EXISTS bottom_buttons (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    group_id BIGINT NOT NULL,
    button_text TEXT NOT NULL,
    reply_text TEXT NOT NULL,
    enabled INTEGER DEFAULT 1,
    created_at TIMESTAMPTZ DEFAULT now(),
    FOREIGN KEY(group_id) REFERENCES group_settings(group_id) ON DELETE CASCADE
);

-- 43. 其他设置表 (自动删除服务消息 / 计算器 / 自动查U)
CREATE TABLE IF NOT EXISTS group_misc_settings (
    group_id BIGINT PRIMARY KEY,
    auto_delete_join INTEGER DEFAULT 1,       -- 自动删除进群消息
    auto_delete_leave INTEGER DEFAULT 1,      -- 自动删除退群消息
    auto_delete_pinned_notice INTEGER DEFAULT 1,  -- 自动删除置顶提示消息
    auto_delete_promotion INTEGER DEFAULT 0, -- 自动删除互推消息
    cancel_channel_pin INTEGER DEFAULT 0,    -- 取消频道消息置顶
    calculator INTEGER DEFAULT 0,            -- 计算器 (群内发送算式返回结果)
    auto_check_u INTEGER DEFAULT 0,          -- 自动查U (发送 TRC20 地址查询余额)
    FOREIGN KEY(group_id) REFERENCES group_settings(group_id) ON DELETE CASCADE
);
-- 44. AI 新闻文章表（RSS 去重，link 唯一）
CREATE TABLE IF NOT EXISTS ai_news_items (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    source TEXT NOT NULL,
    title TEXT NOT NULL,
    link TEXT NOT NULL UNIQUE,
    published_at TEXT DEFAULT '',
    fetched_at TEXT DEFAULT '',
    summary TEXT DEFAULT '',
    sent_breaking INTEGER DEFAULT 0,
    sent_digest INTEGER DEFAULT 0
);

-- 45. AI 新闻每群设置表（不挂 group_settings 外键：默认群可能尚未登记；
--    没行的群 = 不发）
CREATE TABLE IF NOT EXISTS ai_news_settings (
    group_id BIGINT PRIMARY KEY,
    daily_enabled INTEGER DEFAULT 0,
    daily_time TEXT DEFAULT '09:00',
    breaking_enabled INTEGER DEFAULT 0,
    last_digest_date TEXT DEFAULT '',
    breaking_high_signal TEXT DEFAULT '',
    breaking_models TEXT DEFAULT '',
    breaking_events TEXT DEFAULT '',
    max_breaking_per_day INTEGER DEFAULT 10
);

-- 46. AI 新闻发送记录表（按群、按类计突发日限额）
CREATE TABLE IF NOT EXISTS ai_news_sends (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    item_id BIGINT NOT NULL,
    group_id BIGINT NOT NULL,
    kind TEXT NOT NULL,
    sent_at TEXT DEFAULT ''
);
